from __future__ import annotations

"""Build the final invoice for a cancel-at-period-end metered subscription.

The builder pulls the closing period's usage from the aggregation rules, applies
the metered price (included units, per-unit cents), and produces the line that
finance and the customer both see as the last charge on the account.
"""

from metered_usage_models import (
    CancellationContext,
    UsagePrice,
    money_label,
)
from period_aggregation_rules import (
    aggregate_final_period,
    explain_record_decision,
)


def _line_amount(price: UsagePrice, units: int) -> int:
    return price.charge_for_units(units)


def build_final_invoice(context: CancellationContext) -> dict[str, object]:
    """Produce the final invoice for a closing metered subscription."""
    aggregate = aggregate_final_period(context)
    units = int(aggregate["billable_units"])
    amount = _line_amount(context.price, units)
    included = context.price.included_units
    chargeable_units = max(0, units - included)

    return {
        "subscription_id": context.period.subscription_id,
        "currency": context.currency,
        "price_id": context.price.price_id,
        "metered_units": units,
        "included_units": included,
        "chargeable_units": chargeable_units,
        "amount_due_cents": amount,
        "display_amount": money_label(amount, context.currency),
        "billable_record_ids": list(aggregate["billable_record_ids"]),
        "excluded_record_ids": list(aggregate["excluded_record_ids"]),
        "billable_count": aggregate["billable_count"],
        "excluded_count": aggregate["excluded_count"],
        "source": "stripe_final_invoice",
    }


def invoice_line_items(context: CancellationContext) -> list[dict[str, object]]:
    """Return the metered usage line item(s) for the final invoice."""
    invoice = build_final_invoice(context)
    return [
        {
            "description": f"{context.price.nickname} usage (final period)",
            "quantity": invoice["metered_units"],
            "chargeable_units": invoice["chargeable_units"],
            "unit_amount_cents": context.price.unit_amount_cents,
            "amount_cents": invoice["amount_due_cents"],
        }
    ]


def build_final_invoice_with_audit(context: CancellationContext) -> dict[str, object]:
    """Final invoice plus a per-record audit trail for billing review."""
    invoice = build_final_invoice(context)
    audit = [
        explain_record_decision(context.period, rec) for rec in context.records
    ]
    invoice["audit"] = audit
    return invoice


def summarize_final_invoices(invoices: list[dict[str, object]]) -> dict[str, object]:
    """Roll up several final invoices for an end-of-cycle batch run."""
    total = sum(int(inv["amount_due_cents"]) for inv in invoices)
    units = sum(int(inv["metered_units"]) for inv in invoices)
    return {
        "invoice_count": len(invoices),
        "total_amount_cents": total,
        "total_metered_units": units,
        "invoices": invoices,
    }


class FinalInvoiceBuilder:
    """Stateful builder used by the batch end-of-cycle job."""

    def __init__(self) -> None:
        self._invoices: list[dict[str, object]] = []

    def build(self, context: CancellationContext) -> dict[str, object]:
        invoice = build_final_invoice(context)
        self._invoices.append(invoice)
        return invoice

    def build_many(self, contexts: list[CancellationContext]) -> dict[str, object]:
        for ctx in contexts:
            self.build(ctx)
        return summarize_final_invoices(self._invoices)

    def issued(self) -> list[dict[str, object]]:
        return list(self._invoices)

