from __future__ import annotations

"""Domain models for cancel-at-period-end subscriptions on a metered price.

A metered (usage-based) price bills by reported usage events rather than a flat
recurring amount. Each event carries two distinct moments:

- ``usage_timestamp_unix``: when the metered thing actually happened (the API call,
  the GB stored, the minute streamed). This is what Stripe bills against.
- ``reported_at_unix``: when our ingestion pipeline wrote the record. Batches,
  retries, and clock skew mean this can land well after the usage moment, and
  sometimes after the subscription has already been cancelled.

When a subscription is set to ``cancel_at_period_end``, the final invoice closes
out the last billing period. Only usage that belongs to that period should land
on the final invoice.
"""

from dataclasses import dataclass, field


def _require_text(label: str, value: str | None) -> str:
    if value is None or not str(value).strip():
        raise ValueError(f"{label} is required")
    return str(value).strip()


@dataclass(frozen=True)
class UsagePrice:
    """A per-unit metered price (e.g. cents per 1k API calls)."""

    price_id: str
    nickname: str
    unit_amount_cents: int
    included_units: int = 0

    def __post_init__(self) -> None:
        pid = _require_text("price_id", self.price_id)
        nick = _require_text("nickname", self.nickname)
        if self.unit_amount_cents < 0:
            raise ValueError("unit_amount_cents must be non-negative")
        if self.included_units < 0:
            raise ValueError("included_units must be non-negative")
        object.__setattr__(self, "price_id", pid)
        object.__setattr__(self, "nickname", nick)

    def charge_for_units(self, billable_units: int) -> int:
        if billable_units < 0:
            raise ValueError("billable_units must be non-negative")
        chargeable = max(0, billable_units - self.included_units)
        return chargeable * self.unit_amount_cents


@dataclass(frozen=True)
class FinalBillingPeriod:
    """The closing billing period for a subscription cancelling at period end."""

    subscription_id: str
    period_start_unix: int
    period_end_unix: int

    def __post_init__(self) -> None:
        sub = _require_text("subscription_id", self.subscription_id)
        if self.period_end_unix <= self.period_start_unix:
            raise ValueError("period_end_unix must be after period_start_unix")
        object.__setattr__(self, "subscription_id", sub)

    def length_seconds(self) -> int:
        return self.period_end_unix - self.period_start_unix

    # Cancellation takes effect at the end of the period. After this instant the
    # subscription is gone and any usage stamped at-or-after it belongs nowhere.
    def cancellation_effective_unix(self) -> int:
        return self.period_end_unix


@dataclass(frozen=True)
class UsageRecord:
    """A single metered usage event for a subscription item."""

    record_id: str
    subscription_id: str
    quantity: int
    usage_timestamp_unix: int
    reported_at_unix: int

    def __post_init__(self) -> None:
        rid = _require_text("record_id", self.record_id)
        sub = _require_text("subscription_id", self.subscription_id)
        if self.quantity < 0:
            raise ValueError("quantity must be non-negative")
        object.__setattr__(self, "record_id", rid)
        object.__setattr__(self, "subscription_id", sub)

    def is_late_reported(self) -> bool:
        """True when ingestion wrote the record after the usage actually happened."""
        return self.reported_at_unix > self.usage_timestamp_unix

    def billing_instant(self) -> int:
        """The moment this record is attributed to for billing purposes.

        Usage is billed by when it happened, regardless of when the pipeline
        managed to write the row.
        """
        return self.reported_at_unix


@dataclass
class CancellationContext:
    """Inputs needed to close out a cancel-at-period-end subscription."""

    period: FinalBillingPeriod
    price: UsagePrice
    currency: str = "usd"
    records: list[UsageRecord] = field(default_factory=list)

    def __post_init__(self) -> None:
        cur = _require_text("currency", self.currency).lower()
        if len(cur) != 3:
            raise ValueError("currency must be a 3-letter code")
        self.currency = cur
        for rec in self.records:
            if rec.subscription_id != self.period.subscription_id:
                raise ValueError("usage record subscription_id mismatch")

    def add_record(self, record: UsageRecord) -> None:
        if record.subscription_id != self.period.subscription_id:
            raise ValueError("usage record subscription_id mismatch")
        self.records.append(record)


def build_metered_price(
    *,
    price_id: str = "price_metered_api",
    nickname: str = "API calls",
    unit_amount_cents: int,
    included_units: int = 0,
) -> UsagePrice:
    return UsagePrice(
        price_id=price_id,
        nickname=nickname,
        unit_amount_cents=unit_amount_cents,
        included_units=included_units,
    )


def make_usage_record(
    *,
    record_id: str,
    subscription_id: str,
    quantity: int,
    usage_timestamp_unix: int,
    reported_at_unix: int | None = None,
) -> UsageRecord:
    reported = reported_at_unix if reported_at_unix is not None else usage_timestamp_unix
    return UsageRecord(
        record_id=record_id,
        subscription_id=subscription_id,
        quantity=quantity,
        usage_timestamp_unix=usage_timestamp_unix,
        reported_at_unix=reported,
    )


def money_label(cents: int, currency: str) -> str:
    return f"{cents / 100:.2f} {currency.upper()}"

