from __future__ import annotations

"""Decide which usage records belong to the final billing period and total them.

This module owns the period-boundary policy. The final invoice builder asks it
two things: which records fall inside the closing period, and how many units
that comes to. Both questions hinge on which instant a record is attributed to
and on how the period boundaries are compared.
"""

from metered_usage_models import (
    CancellationContext,
    FinalBillingPeriod,
    UsageRecord,
)


def record_instant(record: UsageRecord) -> int:
    """Return the instant a record is attributed to for period bucketing."""
    return record.billing_instant()


def in_final_period(period: FinalBillingPeriod, instant: int) -> bool:
    """Membership test for the closing billing period.

    The period is a window that starts when the cycle opens and runs up to the
    cancellation moment at period end.
    """
    start = period.period_start_unix
    end = period.period_end_unix
    return start <= instant <= end


def partition_records(
    period: FinalBillingPeriod,
    records: list[UsageRecord],
) -> dict[str, list[UsageRecord]]:
    """Split records into those billed on the final invoice and those dropped."""
    billable: list[UsageRecord] = []
    excluded: list[UsageRecord] = []
    for rec in records:
        instant = record_instant(rec)
        if in_final_period(period, instant):
            billable.append(rec)
        else:
            excluded.append(rec)
    return {"billable": billable, "excluded": excluded}


def billable_records(
    period: FinalBillingPeriod,
    records: list[UsageRecord],
) -> list[UsageRecord]:
    return partition_records(period, records)["billable"]


def total_billable_units(
    period: FinalBillingPeriod,
    records: list[UsageRecord],
) -> int:
    return sum(rec.quantity for rec in billable_records(period, records))


def aggregate_final_period(context: CancellationContext) -> dict[str, object]:
    """Aggregate the closing period's usage for one cancellation context."""
    parts = partition_records(context.period, context.records)
    billable = parts["billable"]
    excluded = parts["excluded"]
    units = sum(rec.quantity for rec in billable)
    return {
        "subscription_id": context.period.subscription_id,
        "billable_units": units,
        "billable_record_ids": [rec.record_id for rec in billable],
        "excluded_record_ids": [rec.record_id for rec in excluded],
        "billable_count": len(billable),
        "excluded_count": len(excluded),
        "period_start_unix": context.period.period_start_unix,
        "period_end_unix": context.period.period_end_unix,
    }


def explain_record_decision(
    period: FinalBillingPeriod,
    record: UsageRecord,
) -> dict[str, object]:
    """Diagnostic view of why a single record was kept or dropped."""
    instant = record_instant(record)
    return {
        "record_id": record.record_id,
        "attributed_instant": instant,
        "usage_timestamp_unix": record.usage_timestamp_unix,
        "reported_at_unix": record.reported_at_unix,
        "late_reported": record.is_late_reported(),
        "in_final_period": in_final_period(period, instant),
        "after_cancellation": instant >= period.cancellation_effective_unix(),
    }


def summarize_partition(
    period: FinalBillingPeriod,
    records: list[UsageRecord],
) -> dict[str, int]:
    parts = partition_records(period, records)
    return {
        "total_records": len(records),
        "billable_count": len(parts["billable"]),
        "excluded_count": len(parts["excluded"]),
        "billable_units": sum(r.quantity for r in parts["billable"]),
    }

